from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one match, got {count}")
    return text.replace(old, new, 1)

path = Path("engine/strategy/iterative_search.h")
text = path.read_text()
text = replace_once(
    text,
    '''    struct Stats : BasicAlphaBeta3TT<Evaluator>::Stats {\n        std::uint64_t qnodes = 0, qcutoffs = 0, qlimit_leaves = 0;\n        int seldepth = 0;\n    };''',
    '''    struct Stats : BasicAlphaBeta3TT<Evaluator>::Stats {\n        std::uint64_t qnodes = 0, qcutoffs = 0, qlimit_leaves = 0;\n        std::uint64_t aspiration_attempts = 0, aspiration_fail_low = 0, aspiration_fail_high = 0;\n        int seldepth = 0;\n    };''',
    "aspiration stats",
)
text = replace_once(
    text,
    '''    static constexpr int QuiescenceDepth = 8;\n    static constexpr int MaxPly = 128;''',
    '''    static constexpr int QuiescenceDepth = 8;\n    static constexpr int MaxPly = 128;\n    static constexpr int AspirationDelta = 300; // centipawn-like units; one pawn = 100''',
    "aspiration delta",
)
text = replace_once(
    text,
    '''    void set_quiescence_enabled(bool enabled) {\n        if (quiescence_enabled_ != enabled) experience_.clear();\n        quiescence_enabled_ = enabled;\n    }''',
    '''    void set_quiescence_enabled(bool enabled) {\n        if (quiescence_enabled_ != enabled) experience_.clear();\n        quiescence_enabled_ = enabled;\n    }\n    void set_aspiration_enabled(bool enabled) { aspiration_enabled_ = enabled; }''',
    "aspiration setter",
)
old_root = '''            try {\n                check_stop();\n                auto moves = ordered(position, original, {}, depth >= 4 && result.depth ? result.move : "");\n                int best = -Infinity;\n                std::vector<SearchResult> tied;\n                for (const auto& move : moves) {\n                    check_stop();\n                    Node child;\n                    {\n                        make(position, move);\n                        Undo undo{position};\n                        visit(1);\n                        child = search(position, depth - 1, 1, best, Infinity,\n                                       next_history(root_history, position.hash_key()));\n                    }\n                    const int value = child.value;\n                    if (value > best) { best = value; tied.clear(); }\n                    if (value == best) {\n                        SearchResult candidate;\n                        candidate.move = move; candidate.score = value;\n                        candidate.depth = depth; candidate.has_score = true;\n                        candidate.pv = {move};\n                        candidate.pv.insert(candidate.pv.end(), child.pv.begin(), child.pv.end());\n                        tied.push_back(std::move(candidate));\n                    }\n                }\n                std::sort(tied.begin(), tied.end(), [&](const auto& a, const auto& b) {\n                    return std::find(original.begin(), original.end(), a.move)\n                        < std::find(original.begin(), original.end(), b.move);\n                });\n                auto choice_rng = initial_rng;\n                result = tied[std::uniform_int_distribution<std::size_t>(0, tied.size() - 1)(choice_rng)];\n                rng_ = choice_rng; // consume one tie draw, not one per iteration\n                store_experience(position, depth, result.move);\n                if (completed) completed(result);\n            } catch (const Interrupted&) {'''
new_root = '''            try {\n                check_stop();\n                struct RootAttempt {\n                    int best = -Infinity;\n                    std::vector<SearchResult> tied;\n                };\n                auto run_root = [&](int window_alpha, int window_beta) {\n                    RootAttempt attempt;\n                    auto moves = ordered(position, original, {}, depth >= 4 && result.depth ? result.move : "");\n                    int alpha = window_alpha;\n                    for (const auto& move : moves) {\n                        check_stop();\n                        Node child;\n                        {\n                            make(position, move);\n                            Undo undo{position};\n                            visit(1);\n                            child = search(position, depth - 1, 1, alpha, window_beta,\n                                           next_history(root_history, position.hash_key()));\n                        }\n                        const int value = child.value;\n                        if (value > attempt.best) { attempt.best = value; attempt.tied.clear(); }\n                        if (value == attempt.best) {\n                            SearchResult candidate;\n                            candidate.move = move; candidate.score = value;\n                            candidate.depth = depth; candidate.has_score = true;\n                            candidate.pv = {move};\n                            candidate.pv.insert(candidate.pv.end(), child.pv.begin(), child.pv.end());\n                            attempt.tied.push_back(std::move(candidate));\n                        }\n                        alpha = std::max(alpha, attempt.best);\n                        if (attempt.best >= window_beta) break;\n                    }\n                    return attempt;\n                };\n\n                RootAttempt attempt;\n                const bool use_aspiration = aspiration_enabled_ && result.has_score && depth >= 2;\n                if (use_aspiration) {\n                    ++stats_.aspiration_attempts;\n                    const int lower = std::max(-Infinity, result.score - AspirationDelta);\n                    const int upper = std::min(Infinity, result.score + AspirationDelta);\n                    attempt = run_root(lower, upper);\n                    if (attempt.best <= lower) {\n                        ++stats_.aspiration_fail_low;\n                        attempt = run_root(-Infinity, Infinity);\n                    } else if (attempt.best >= upper) {\n                        ++stats_.aspiration_fail_high;\n                        attempt = run_root(-Infinity, Infinity);\n                    }\n                } else {\n                    attempt = run_root(-Infinity, Infinity);\n                }\n                if (attempt.tied.empty()) throw std::logic_error("root search produced no move");\n                std::sort(attempt.tied.begin(), attempt.tied.end(), [&](const auto& a, const auto& b) {\n                    return std::find(original.begin(), original.end(), a.move)\n                        < std::find(original.begin(), original.end(), b.move);\n                });\n                auto choice_rng = initial_rng;\n                result = attempt.tied[std::uniform_int_distribution<std::size_t>(0, attempt.tied.size() - 1)(choice_rng)];\n                rng_ = choice_rng; // consume one tie draw, not one per iteration\n                store_experience(position, depth, result.move);\n                if (completed) completed(result);\n            } catch (const Interrupted&) {'''
text = replace_once(text, old_root, new_root, "aspiration root search")
text = replace_once(
    text,
    '''    bool experience_enabled_ = false;\n    bool quiescence_enabled_ = true;\n    bool experience_allowed_ = false;''',
    '''    bool experience_enabled_ = false;\n    bool quiescence_enabled_ = true;\n    bool aspiration_enabled_ = true;\n    bool experience_allowed_ = false;''',
    "aspiration member",
)
path.write_text(text)

path = Path("tests/search_test.cpp")
text = path.read_text()
text = replace_once(
    text,
    '''        strategy::FeatureAlphaBeta3TT fixed;\n        strategy::IterativeSearch features;\n        features.set_quiescence_enabled(false);\n        p = rules::Position();\n        for (unsigned sample = 0; sample < 6; ++sample) {\n            fixed.set_seed(70000 + sample); features.set_seed(70000 + sample);\n            const auto expected = fixed.choose(p);\n            strategy::SearchControl control;\n            const auto actual = features.choose(p, 3, control);\n            require(actual.move == expected && actual.score == fixed.last_score(), "v0.0.13 depth-three compatibility");\n            validate_pv(p, actual); play(p, expected);\n        }\n        std::cout << "PASS v0.0.13 exact depth-three move/score equivalence on six opening positions\\n";''',
    '''        strategy::FeatureAlphaBeta3TT fixed;\n        strategy::IterativeSearch features;\n        strategy::IterativeSearch baseline_aspiration_off;\n        features.set_quiescence_enabled(false);\n        baseline_aspiration_off.set_quiescence_enabled(false);\n        baseline_aspiration_off.set_aspiration_enabled(false);\n        std::uint64_t baseline_nodes = 0, aspiration_nodes = 0, aspiration_attempts = 0, aspiration_failures = 0;\n        p = rules::Position();\n        for (unsigned sample = 0; sample < 6; ++sample) {\n            fixed.set_seed(70000 + sample);\n            features.set_seed(70000 + sample);\n            baseline_aspiration_off.set_seed(70000 + sample);\n            const auto expected = fixed.choose(p);\n            auto baseline_position = p.clone();\n            strategy::SearchControl baseline_control;\n            const auto baseline = baseline_aspiration_off.choose(baseline_position, 3, baseline_control);\n            strategy::SearchControl control;\n            const auto actual = features.choose(p, 3, control);\n            require(actual.move == expected && actual.score == fixed.last_score(), "v0.0.13 depth-three compatibility");\n            require(actual.move == baseline.move && actual.score == baseline.score, "aspiration preserves fixed-depth move and score");\n            baseline_nodes += baseline_aspiration_off.last_stats().nodes;\n            aspiration_nodes += features.last_stats().nodes;\n            aspiration_attempts += features.last_stats().aspiration_attempts;\n            aspiration_failures += features.last_stats().aspiration_fail_low + features.last_stats().aspiration_fail_high;\n            validate_pv(p, actual); play(p, expected);\n        }\n        std::cout << "DIAG aspiration nodes baseline=" << baseline_nodes << " candidate=" << aspiration_nodes\n                  << " delta_pct=" << (100.0 * (double(aspiration_nodes) - baseline_nodes) / baseline_nodes)\n                  << " attempts=" << aspiration_attempts << " failures=" << aspiration_failures << '\\n';\n        std::cout << "PASS v0.0.13 exact depth-three move/score equivalence on six opening positions\\n";''',
    "aspiration fixed-depth comparison",
)
path.write_text(text)
